APX.tr = {"country":{"name":"Türkiye","tagline":"The world's sixth-largest vineyard, almost all for eating, with a small and stubborn wine scene built on Öküzgözü, Boğazkere, Kalecik Karası and Emir.","classification":"Türkiye has no operational appellation system for wine comparable to the EU's; labels name grapes, wineries and broad regions (Thrace, Aegean, Cappadocia, Eastern Anatolia). A few geographical indications exist for grapes and other products, and producer groups such as Thrace's 'Trakya' wine route promote regional identity."},"regions":[{"name":"Thrace and Marmara","slug":"thrace-and-marmara","tagline":"European Türkiye between three seas: the industry's historic base.","ids":["tr-bozcaada","tr-thrace"]},{"name":"Aegean","slug":"aegean","tagline":"The largest wine region by volume: Urla, Bozcaada, Denizli and Manisa.","ids":["tr-urla"]},{"name":"Central Anatolia and Cappadocia","slug":"central-anatolia-and-cappadocia","tagline":"Volcanic tuff, cave cellars and Emir; Kalecik Karası near Ankara.","ids":["tr-cappadocia"]},{"name":"Eastern and Southeastern Anatolia","slug":"eastern-and-southeastern-anatolia","tagline":"The Euphrates highlands of Öküzgözü and Boğazkere, and Syriac wine in Mardin.","ids":["tr-elazig-diyarbakir"]}],"items":{"tr-thrace":{"name":"Thrace (Trakya)","cat":"Wine region","region":"Thrace and Marmara","created":"Traditional region; Türkiye has no national appellation system","styles":["red","white"],"grapes":"Papaskarası, Adakarası, Cabernet Sauvignon, Merlot, Syrah, Sauvignon Blanc, Narince","summary":"European Türkiye between the Black Sea, the Sea of Marmara and the Aegean is the country's leading quality wine area, especially around Tekirdağ (Şarköy and Mürefte) and Kırklareli. The Marmara moderates the climate, giving warm summers and mild winters.","terroir":"Clay, sand and limestone; maritime influence of the Marmara and Black Sea.","producers":["Barbare","Chamlija","Gali","Arcadia","Doluca"],"nerd_note":"Mürefte and Şarköy on the Marmara coast were wine villages of Ottoman Greek communities until the population exchange of 1923.","rslug":"thrace-and-marmara"},"tr-bozcaada":{"name":"Bozcaada","cat":"Wine region","region":"Thrace and Marmara","created":"Traditional island wine area","styles":["white","red"],"grapes":"Kuntra (Karalahna), Çavuş, Vasilaki","summary":"Bozcaada, the ancient Tenedos, is a small windswept island in the Aegean off Çanakkale, near the site of Troy. Its vineyards, cooled by constant northerly winds, keep native grapes found almost nowhere else.","terroir":"Sandy and limestone soils; strong winds; maritime climate.","producers":["Corvus","Talay","Amadeus"],"nerd_note":"Homer's Iliad names Tenedos, where the Greek fleet hid before the Trojan horse was brought into Troy.","rslug":"thrace-and-marmara"},"tr-urla":{"name":"Urla","cat":"Wine region","region":"Aegean","created":"Wine route of the İzmir peninsula","styles":["red","white"],"grapes":"Urla Karası, Bornova Misketi, Boğazkere, Syrah, Cabernet","summary":"Urla, on the peninsula west of İzmir, has become the centre of Türkiye's boutique wine scene, with a wine route linking a dozen small estates among olive groves. Sea breezes from the Aegean temper hot summers.","terroir":"Limestone and clay; maritime Aegean climate.","producers":["Urla Şarapçılık","USCA","Mozaik","Usca"],"nerd_note":"Klazomenai, an Ionian Greek city near Urla, has an excavated sixth-century BC olive oil workshop, and the peninsula's farmers grew vines and olives side by side for millennia.","rslug":"aegean"},"tr-cappadocia":{"name":"Cappadocia (Kapadokya)","cat":"Wine region","region":"Central Anatolia and Cappadocia","created":"Traditional region","styles":["white","red"],"grapes":"Emir, Narince, Kalecik Karası, Öküzgözü","summary":"Cappadocia's volcanic plateau around Nevşehir and Ürgüp lies at about 1,000 to 1,400 metres, with continental winters and hot, dry summers. Bush vines grow in volcanic ash among the fairy chimneys, and wine is aged in cellars carved into the soft tuff.","terroir":"Volcanic tuff and ash; about 1,000 to 1,400 m; continental climate.","producers":["Turasan","Kocabağ","Kayra"],"nerd_note":"Emir, Cappadocia's native white, makes crisp, light wines; Kalecik Karası, from Kalecik near Ankara, was rescued from near extinction by researchers at Ankara University.","rslug":"central-anatolia-and-cappadocia"},"tr-elazig-diyarbakir":{"name":"Elazığ and Diyarbakır","cat":"Wine region","region":"Eastern and Southeastern Anatolia","created":"Traditional region","styles":["red"],"grapes":"Öküzgözü, Boğazkere","summary":"The upper Euphrates and Tigris country of eastern Anatolia is the home of Türkiye's two great native reds: Öküzgözü ('ox eye'), juicy and soft, from around Elazığ, and Boğazkere ('throat burner'), dark and tannic, from around Diyarbakır. Summers are very hot and winters cold.","terroir":"Continental highland climate; clay and limestone soils.","producers":["Kavaklıdere (buys grapes)","Doluca (buys grapes)","Kayra"],"nerd_note":"Many of the region's vineyards were flooded by the reservoir of the Keban Dam on the Euphrates in the 1970s.","rslug":"eastern-and-southeastern-anatolia"}}};
